class Hund:
    def __init__(self, name):
        self.name = name        # Attribut

    def bellen(self):
        print(f"{self.name} sagt Wuff!")

h = Hund("Rex")    # Objekt erzeugen
h.bellen()          # Rex sagt Wuff!
print(h.name)       # Rex

class Konto:
    def __init__(self, start):
        self._stand = start     # Konvention: privat

    def einzahlen(self, betrag):
        if betrag > 0:
            self._stand += betrag

    @property
    def stand(self):            # Getter
        return self._stand

k = Konto(100)
k.einzahlen(50)
print(k.stand)   # 150 (lesen via Getter)

class Tier:
    def __init__(self, name):
        self.name = name
    def gib_laut(self):
        return "..."

class Hund(Tier):
    def __init__(self, name):
        super().__init__(name)
    def gib_laut(self):        # überschreiben
        return "Wuff"

h = Hund("Rex")
print(h.gib_laut())   # Wuff
print(isinstance(h, Tier))   # True
